INSERT INTO `relic_suits` VALUES (300002,'雪幽魂','xueyouhun','防御加成30%','造成伤害时，有15%（若目标带有减速效果则为30%）基础概率冰冻1回合；受到攻击时，使攻击者减速30点，持续1回合。',0);
INSERT INTO `relic_suits` VALUES (300003,'地藏像','dizangxiang','生命加成15%','受到暴击时，自身100%、友方30%概率获得1回合护盾，能吸收10%生命上限的伤害；对被嘲讽目标降低60%触发概率。',0);
INSERT INTO `relic_suits` VALUES (300004,'蝠翼','fuyi','攻击加成15%','造成伤害时，附带20%吸血。',0);
INSERT INTO `relic_suits` VALUES (300006,'涅槃之火','niepanzhihuo','生命加成15%','行动结束时，若生命比例低于30%，治疗生命上限15%的生命。',0);
INSERT INTO `relic_suits` VALUES (300007,'三味','sanwei','暴击15%','任一友方承受控制效果和放逐时，使其提升30点速度，持续2回合，此增益效果不可驱散，可叠加2层。',0);
INSERT INTO `relic_suits` VALUES (300008,'魍魉之匣','wangliangzhixia','效果抵抗15%','造成伤害时，有25%基础概率随机附加眩晕、沉默、减疗40%、混乱，持续1回合。',0);
INSERT INTO `relic_suits` VALUES (300009,'被服','beifu','生命加成15%','30%减伤。',0);
INSERT INTO `relic_suits` VALUES (300010,'招财猫','zhaocaimao','防御加成30%','回合开始时，有50%的概率获得2点鬼火。',0);
INSERT INTO `relic_suits` VALUES (300011,'反枕','fanzhen','防御加成30%','造成伤害时，有23%基础概率使目标沉睡1回合。',0);
INSERT INTO `relic_suits` VALUES (300012,'轮入道','lunrudao','攻击加成15%','回合结束时，有20%概率获得新的回合。',0);
INSERT INTO `relic_suits` VALUES (300013,'日女巳时','rinvyishi','防御加成30%','造成伤害时，有20%概率击退目标30%行动条，若其带有增益状态、印记，触发概率提升10%。',0);
INSERT INTO `relic_suits` VALUES (300014,'镜姬','jingji','生命加成15%','受到伤害时，有30%概率造成100%反伤；对被嘲讽目标降低60%触发概率。',0);
INSERT INTO `relic_suits` VALUES (300015,'钟灵','zhongling','生命加成15%','造成伤害时，有10%基础概率使目标眩晕1回合。若敌方无人处于眩晕中，则基础概率改为20%。',0);
INSERT INTO `relic_suits` VALUES (300018,'狰','zheng','攻击加成15%','受到敌方伤害时，有35%概率反击；对被嘲讽目标降低60%触发概率。',0);
INSERT INTO `relic_suits` VALUES (300019,'火灵','huoling','效果命中15%','战斗开始时，获得3点鬼火。',0);
INSERT INTO `relic_suits` VALUES (300020,'鸣屋','mingwu','攻击加成15%','攻击时，若目标带有控制效果，提升45%伤害。',0);
INSERT INTO `relic_suits` VALUES (300021,'薙魂','zhihun','生命加成15%','唯一效果。友方被攻击时50%概率守护，使其中的单体伤害降低20%，再分担50%，直到攻击结束。每次攻击最多触发一次。',0);
INSERT INTO `relic_suits` VALUES (300022,'心眼','xinyan','攻击加成15%','造成伤害时，目标生命比例每降低15%，提升10%伤害。',0);
INSERT INTO `relic_suits` VALUES (300023,'木魅','mumei','防御加成30%','任何友方受到伤害时，有25%概率削减伤害者1点鬼火，单次攻击内最多触发1次；对被嘲讽目标降低60%触发概率。',0);
INSERT INTO `relic_suits` VALUES (300024,'树妖','shuyao','生命加成15%','治疗时，增加20%（若目标生命低于20%，改为增加50%）基础治疗。',0);
INSERT INTO `relic_suits` VALUES (300026,'网切','wangqie','暴击15%','攻击时，50%概率无视45%防御。',0);
INSERT INTO `relic_suits` VALUES (300027,'阴摩罗','yinmoluo','攻击加成15%','击败目标时，获得3点鬼火。',0);
INSERT INTO `relic_suits` VALUES (300029,'伤魂鸟','shanghunniao','暴击15%','任一非怪物目标阵亡时，治疗生命上限20%的生命，并提升20%伤害（上限120%）直到战斗结束。',0);
INSERT INTO `relic_suits` VALUES (300030,'破势','poshi','暴击15%','造成伤害时，若目标生命比例高于70%，提升40%伤害。',0);
INSERT INTO `relic_suits` VALUES (300031,'镇墓兽','zhenmushou','暴击15%','生命比例每降低1%，提升暴击伤害的0.5%。',0);
INSERT INTO `relic_suits` VALUES (300032,'珍珠','zhenzhu','防御加成30%','治疗时，目标获得不可驱散的护盾2回合，能吸收等同基础治疗30%的伤害。',0);
INSERT INTO `relic_suits` VALUES (300033,'骰子鬼','touzigui','效果抵抗15%','抵抗时，反击来源目标，该次反击提升50%伤害。未被控制时承受控制效果，增加25%行动条。',0);
INSERT INTO `relic_suits` VALUES (300034,'蚌精','bengjing','效果命中15%','战斗开始时，友方全体获得无法驱散的护盾1回合，能吸收等同生命上限10%的伤害。',0);
INSERT INTO `relic_suits` VALUES (300035,'魅妖','meiyao','防御加成30%','造成伤害时，有25%基础概率使目标混乱1回合。',0);
INSERT INTO `relic_suits` VALUES (300036,'针女','zhennv','暴击15%','暴击时，有40%概率对目标造成其生命上限10%的无视防御伤害，最高不超过攻击120%。',0);
INSERT INTO `relic_suits` VALUES (300039,'返魂香','fanhunxiang','效果抵抗15%','受到伤害时，有25%基础概率使伤害者眩晕1回合；对被嘲讽目标降低60%触发概率。',0);
INSERT INTO `relic_suits` VALUES (300048,'狂骨','kuanggu','攻击加成15%','造成伤害时，每拥有1点鬼火，提升8%伤害。',0);
INSERT INTO `relic_suits` VALUES (300049,'幽谷响','youguxiang','效果抵抗15%','抵抗控制效果时，有50%概率将该效果反弹给来源目标，且必定命中。',0);
INSERT INTO `relic_suits` VALUES (300050,'土蜘蛛','tuzhizhu','','唯一被动，对怪物造成伤害时，为其附加1层土蜘蛛印记，降低10%速度，并造成10%间接伤害，持续1回合。上限3层。',1);
INSERT INTO `relic_suits` VALUES (300051,'胧车','longche','','唯一被动，受到怪物攻击时，有50%概率增加30%行动条，单次攻击内最多触发1次。',1);
INSERT INTO `relic_suits` VALUES (300052,'荒骷髅','huangkulou','','唯一被动，提升10%对怪物伤害，若受到怪物攻击，提升伤害效果改为25%，持续1回合',1);
INSERT INTO `relic_suits` VALUES (300053,'地震鲶','dizhennian','','唯一被动，与怪物的战斗开始时，获得60%减伤；每次受到伤害，将6%减伤转化为提升1.5%伤害，单次攻击内最多触发1次。',1);
INSERT INTO `relic_suits` VALUES (300054,'蜃气楼','shenqilou','','唯一被动，与怪物的战斗开始时，获得庇护。庇护会在消失后5回合重新获得。',1);
INSERT INTO `relic_suits` VALUES (300055,'片叶之苇','pianyezhiwei','暴击15%','当前生命等于最大生命时，造成伤害提升45%。',0);
INSERT INTO `relic_suits` VALUES (300056,'尘冢','chenzhong','攻击加成15%','行动时获得尘冢：造成的伤害提升25%，友方非召唤物目标每比敌方多一个，伤害额外提升4%，最多提升至45%。',0);
INSERT INTO `relic_suits` VALUES (300057,'油赤子','youchizi','效果命中15%','唯一效果。战斗开始时获得2层灵元，灵元：每层提升友方全体8%的防御，友方施放妖术时若鬼火不足，可替代等量鬼火。',0);
INSERT INTO `relic_suits` VALUES (300058,'夜啼石','yetishi','生命加成15%','唯一效果。友方非召唤物目标阵亡时，获得其初始攻击、防御与生命的30% ，持续2回合（上限5层，且最多不超过携带者初始属性的150%）。',0);
INSERT INTO `relic_suits` VALUES (300059,'夜送犬','yesongquan','效果抵抗15%','每回合首次受到来自敌方的控制效果时，获得1层夜行。夜行：提升80%抵抗，上限3层，携带者回合开始处于可行动状态时移除。',0);
INSERT INTO `relic_suits` VALUES (300060,'雨降','yujiang','防御加成30%','生命首次低于30%时，将自身生命上限降低至1点并获得3层雨露。雨露：受到伤害时，消耗1层并吸收此次行动内的所有伤害。',0);
INSERT INTO `relic_suits` VALUES (300073,'飞缘魔','feiyuanmo','效果命中15%','附加负面状态时，无视30%总效果抵抗。',0);
INSERT INTO `relic_suits` VALUES (300074,'兵主部','bingzhubu','攻击加成15%','回合结束后，获得1层兵刃（增益，状态）。每层将在造成伤害时无视目标75点防御，上限3层。',0);
INSERT INTO `relic_suits` VALUES (300075,'青女房','qingnvfang','暴击15%','首次受到致命伤害时，移除所有状态和印记，恢复100%生命并使自身冰封1回合，期间提升100%防御、免疫所有减益。若冰封结束时仍存活，则再次恢复100%生命。每回目仅触发一次。',0);
INSERT INTO `relic_suits` VALUES (300076,'涂佛','tufo','生命加成15%','唯一效果。回合结束时，若本回合普攻或无法动作，使友方全体提升15%效果抵抗、伤害，维持2回合，自身提升双倍。',0);
INSERT INTO `relic_suits` VALUES (300077,'鬼灵歌伎','guilinggeji','','唯一被动，每对怪物造成5次伤害后，下一次对怪物造成伤害将会对其造成生命上限20%的无视防御伤害，最高不超过攻击的255%。',1);
INSERT INTO `relic_suits` VALUES (300079,'遗念火','yinianhuo','效果命中15%','携带者回合开始时获得1层念火（上限3层），每层提供15%效果抵抗，携带者施放技能时优先消耗自身念火替代等量鬼火。',0);
INSERT INTO `relic_suits` VALUES (300080,'共潜','gongqian','效果抵抗15%','回合结束时随机驱散己方1个负面状态，若回合中未造成伤害，则额外随机驱散己方2个负面状态。',0);
INSERT INTO `relic_suits` VALUES (300081,'恶楼','elou','生命加成15%','战斗开始时，获得恶楼之力（增伤80%、减伤80%）。在携带者的前8回合，恶楼之力暂时被封禁。',0);
INSERT INTO `relic_suits` VALUES (300082,'贝吹坊','beichuifang','攻击加成15%','携带者回合开始获得一层可以抵挡一次伤害的贝甲，贝甲存在时提高25%的伤害。',0);
INSERT INTO `relic_suits` VALUES (300083,'海月火玉','haiyuehuoyu','暴击15%','鬼火、愿力或义火足够时，施放妖术额外消耗1点鬼火、愿力或义火并提升40%伤害。',0);
INSERT INTO `relic_suits` VALUES (300084,'出世螺','chushiluo','防御加成30%','每次受到伤害后恢复该伤害10%的生命值。在战斗开始与自身行动前获得螺壳（上限1层），单次受到超过最大生命值的60%的伤害时，将该伤害降低为最大生命值的60%，并移除螺壳。',0);
INSERT INTO `relic_suits` VALUES (300085,'火之车','huozhiche','防御加成30%','携带者回合结束时，获得1层墓火，累计4层时清空层数并获得1个回合，且该回合鬼火消耗减少1点。',0);
INSERT INTO `relic_suits` VALUES (300086,'隐念','yinnian','攻击加成15%','造成的伤害提升20%，若对同一目标重复造成伤害，造成的伤害依次提升至40%、60%，之后从20%开始循环判定。',0);
INSERT INTO `relic_suits` VALUES (300087,'叠叩','diekou','生命加成15%','（唯一效果）若自身初始暴击超过120%时，全体非召唤物友方减少15%受到的暴击伤害。',0);
INSERT INTO `relic_suits` VALUES (300088,'应声虫','yingshengchong','暴击15%','携带者获得20%协战概率。',0);
INSERT INTO `relic_suits` VALUES (300089,'元兴寺','yuanxingsi','效果命中15%','（唯一效果）携带者回合内造成控制效果时，每命中1个目标，使全体非召唤物友方造成的伤害提升5%（单次控制重复命中同目标时，仅生效1次），最多提升40%，持续2回合。',0);
INSERT INTO `relic_suits` VALUES (300090,'钓瓶火','diaopinghuo','效果抵抗15%','回合结束后，额外推进1格鬼火行动条，并为当前生命比例最低的非召唤物友方目标治疗自身防御700%的生命。',0);
INSERT INTO `relic_suits` VALUES (300091,'夜荒魂','yehuanghun','','唯一被动，携带者回合内对怪物造成控制效果或放逐时，每命中1个目标，使全体非召唤物友方提升15点速度（单次控制重复命中同目标时，仅生效1次），最多提升90点，维持1回合。',1);
INSERT INTO `relic_suits` VALUES (300092,'无刀取','wudaoqu','暴击伤害20%','回合结束后，永久提升15%的伤害，最高不超过45%。',0);
INSERT INTO `relic_suits` VALUES (300093,'奉海图','fenghaitu','防御加成30%','唯一效果，友方受到攻击时获得海图守护，持续1回合。海图守护：降低此次伤害的30%（不超过携带者生命上限的35%）并记录，消失时失去等同于记录值的生命。',0);
INSERT INTO `relic_suits` VALUES (300094,'八咫镜','bazhijing','','唯一效果。与怪物战斗时，造成伤害施加光灼，再次施加光灼时移除并提升20%伤害。',1);
INSERT INTO `relic_suits` VALUES (300095,'天羽羽斩','tianyuyuzhan','','与怪物战斗时，战斗开始获得50点无视防御。',1);
INSERT INTO `relic_suits` VALUES (300096,'预言星盘','yuyanxingpan','','唯一效果。与怪物战斗时施放妖术技能，提升阴阳师暴击，提升值为自身暴击的15%。',1);
INSERT INTO `relic_suits` VALUES (300097,'月之石','yuezhishi','','唯一效果。友方召唤物存在时，敌方怪物总效果抵抗降低30%（不超过自身初始效果抵抗的50%）。',1);
INSERT INTO `relic_suits` VALUES (300098,'纺缘锤','fangyuanchui','','战斗开始与自身每个回合开始时获得缘守。缘守：受到怪物攻击后格挡500点伤害，格挡初始防御300%的伤害后移除。',1);
INSERT INTO `relic_suits` VALUES (300099,'稻荷穗箭','daohesuijian','','唯一效果。与怪物战斗时，回合结束后提升阴阳师10%行动条（阴阳师回合开始前限1次）。',1);
